    }

    if (filters.assignedTo) {
      conditions.push(`tasks.assigned_to = $${paramIndex++}`);
      values.push(filters.assignedTo);
    }

    if (filters.search) {
      conditions.push(`(tasks.title ILIKE $${paramIndex} OR tasks.description ILIKE $${paramIndex})`);
